function calculatePrice(item) {
  const base = item.price * (1 - item.discount);
  const tax = base * 0.08;
  return Math.round((base + tax) * 100) / 100;
}

function finalAmount(product) {
  const base = product.price * (1 - product.discount);
  const tax = base * 0.08;
  return Math.round((base + tax) * 100) / 100;
}

class OrderService {
  process(order) {
    if (!order.items || order.items.length === 0) throw new Error("empty");
    const total = order.items.reduce((s,i)=>s+i.price*i.qty,0);
    return { id: order.id, total };
  }
}

class InvoiceService {
  finalize(invoice) {
    if (!invoice.items || invoice.items.length === 0) throw new Error("empty");
    const amount = invoice.items.reduce((s,i)=>s+i.price*i.qty,0);
    return { id: invoice.id, amount };
  }
}

